import os
import hashlib
import hmac
import time
import json
import struct
import secrets
from functools import lru_cache
from typing import Optional, Dict, List, Tuple

# Security configuration
SECRET_KEY = os.urandom(32)
SESSION_DURATION = 3600
MAX_FAILED_ATTEMPTS = 5
LOCKOUT_DURATION = 300

# Role hierarchy: higher numeric value = more privilege
ROLE_HIERARCHY = {
    'guest': 0,
    'user': 1,
    'moderator': 2,
    'admin': 3,
    'superadmin': 4
}

# Resource access requirements
RESOURCE_ACL = {
    '/api/public': 0,
    '/api/profile': 1,
    '/api/moderate': 2,
    '/api/admin/users': 3,
    '/api/admin/system': 4,
    '/api/admin/secrets': 4
}

class RateLimiter:
    def __init__(self):
        self._attempts: Dict[str, List[float]] = {}
        self._lockouts: Dict[str, float] = {}

    def check_rate_limit(self, client_id: str) -> bool:
        now = time.time()
        if client_id in self._lockouts:
            if now - self._lockouts[client_id] < LOCKOUT_DURATION:
                return False
            del self._lockouts[client_id]
        return True

    def record_failure(self, client_id: str):
        now = time.time()
        if client_id not in self._attempts:
            self._attempts[client_id] = []
        self._attempts[client_id] = [
            t for t in self._attempts[client_id] if now - t < 60
        ] + [now]
        if len(self._attempts[client_id]) >= MAX_FAILED_ATTEMPTS:
            self._lockouts[client_id] = now
            self._attempts[client_id] = []

class SecureTokenManager:
    """Handles token generation and validation with anti-tampering measures."""

    def __init__(self, secret: bytes):
        self._secret = secret
        self._revoked: set = set()

    def generate_token(self, user_id: str, role_level: int, metadata: dict = None) -> str:
        """Generate a signed token with role information encoded."""
        token_id = secrets.token_hex(16)
        issued_at = int(time.time())
        expires_at = issued_at + SESSION_DURATION

        # Pack the payload with role level as a signed 32-bit integer
        # This allows for future extension with negative values for special roles
        payload = {
            'tid': token_id,
            'uid': user_id,
            'rlv': role_level,  # role level value
            'iat': issued_at,
            'exp': expires_at,
            'meta': metadata or {}
        }

        payload_bytes = json.dumps(payload, separators=(',', ':')).encode('utf-8')
        signature = hmac.new(self._secret, payload_bytes, hashlib.sha256).digest()

        # Token format: base64(payload) + '.' + base64(signature)
        import base64
        token = base64.urlsafe_b64encode(payload_bytes).decode() + '.' + \
                base64.urlsafe_b64encode(signature).decode()
        return token

    def validate_token(self, token: str) -> Optional[dict]:
        """Validate token signature and expiration."""
        import base64
        try:
            parts = token.split('.')
            if len(parts) != 2:
                return None

            payload_bytes = base64.urlsafe_b64decode(parts[0])
            provided_sig = base64.urlsafe_b64decode(parts[1])

            # Constant-time signature comparison
            expected_sig = hmac.new(self._secret, payload_bytes, hashlib.sha256).digest()
            if not hmac.compare_digest(expected_sig, provided_sig):
                return None

            payload = json.loads(payload_bytes)

            # Check expiration
            if time.time() > payload.get('exp', 0):
                return None

            # Check revocation
            if payload.get('tid') in self._revoked:
                return None

            return payload
        except Exception:
            return None

    def revoke_token(self, token_id: str):
        self._revoked.add(token_id)


class AccessController:
    """Enforces role-based access control with defense in depth."""

    def __init__(self):
        self._token_mgr = SecureTokenManager(SECRET_KEY)
        self._rate_limiter = RateLimiter()
        self._audit_log: List[dict] = []

    def authenticate(self, username: str, password_hash: str, client_id: str) -> Optional[str]:
        """Authenticate user and return a session token."""
        if not self._rate_limiter.check_rate_limit(client_id):
            self._audit('auth_blocked', client_id, username)
            return None

        user = self._lookup_user(username)
        if user is None:
            self._rate_limiter.record_failure(client_id)
            self._audit('auth_failed', client_id, username)
            return None

        if not hmac.compare_digest(
            password_hash.encode(),
            user['password_hash'].encode()
        ):
            self._rate_limiter.record_failure(client_id)
            self._audit('auth_failed', client_id, username)
            return None

        role_level = self._resolve_role_level(user['role'])
        token = self._token_mgr.generate_token(username, role_level)
        self._audit('auth_success', client_id, username)
        return token

    def check_access(self, token: str, resource: str, client_id: str) -> Tuple[bool, str]:
        """Check if the token grants access to the requested resource.

        Returns (allowed, reason) tuple.
        Defense in depth: validates token, checks role level, verifies resource exists.
        """
        if not self._rate_limiter.check_rate_limit(client_id):
            return False, 'rate_limited'

        payload = self._token_mgr.validate_token(token)
        if payload is None:
            return False, 'invalid_token'

        required_level = RESOURCE_ACL.get(resource)
        if required_level is None:
            return False, 'resource_not_found'

        # Extract the user's role level from the validated token
        user_role_level = payload.get('rlv', 0)

        # Security check: ensure role level is within valid bounds
        # Role levels are stored as signed integers for extensibility
        # Negative values are reserved for system accounts (future use)
        if not isinstance(user_role_level, int):
            return False, 'invalid_role_format'

        # Access decision: user's role level must meet or exceed required level
        if user_role_level >= required_level:
            self._audit('access_granted', client_id, payload.get('uid'), resource)
            return True, 'granted'

        self._audit('access_denied', client_id, payload.get('uid'), resource)
        return False, 'insufficient_privileges'

    def _resolve_role_level(self, role_name: str) -> int:
        """Convert role name to numeric level."""
        return ROLE_HIERARCHY.get(role_name, 0)

    def _lookup_user(self, username: str) -> Optional[dict]:
        """Simulated user lookup - in production this queries a database."""
        # Placeholder - returns None for unknown users
        users_db = {
            'alice': {'password_hash': 'a]f8c5e8...', 'role': 'admin'},
            'bob': {'password_hash': 'b2d9f1a4...', 'role': 'user'},
            'guest': {'password_hash': 'deadbeef...', 'role': 'guest'}
        }
        return users_db.get(username)

    def _audit(self, event: str, client_id: str, *args):
        self._audit_log.append({
            'time': time.time(),
            'event': event,
            'client': client_id,
            'details': args
        })


def handle_request(controller: AccessController, request: dict) -> dict:
    """Main request handler with input validation."""
    action = request.get('action')
    client_id = request.get('client_id', 'unknown')

    if action == 'login':
        username = request.get('username', '')
        password = request.get('password', '')

        # Input validation
        if not username or not password:
            return {'status': 'error', 'message': 'missing credentials'}
        if len(username) > 64 or len(password) > 128:
            return {'status': 'error', 'message': 'input too long'}

        # Hash password client-side simulation
        pw_hash = hashlib.sha256(password.encode()).hexdigest()

        token = controller.authenticate(username, pw_hash, client_id)
        if token:
            return {'status': 'ok', 'token': token}
        return {'status': 'error', 'message': 'authentication failed'}

    elif action == 'access':
        token = request.get('token', '')
        resource = request.get('resource', '')

        if not token or not resource:
            return {'status': 'error', 'message': 'missing parameters'}

        # Validate resource path format
        if not resource.startswith('/api/'):
            return {'status': 'error', 'message': 'invalid resource path'}
        if '..' in resource or '\\' in resource:
            return {'status': 'error', 'message': 'invalid resource path'}

        allowed, reason = controller.check_access(token, resource, client_id)
        return {'status': 'ok' if allowed else 'denied', 'reason': reason}

    return {'status': 'error', 'message': 'unknown action'}
